public async Task<List<Result>> ProcessPipelineAsync(List<Input> inputs)
{
    var results = new List<Result>();

    foreach (var input in inputs)
    {
        var step1 = await Step1Async(input);
        var step2 = await Step2Async(step1);
        results.Add(step2);
    }

    return results;
}

private async Task<Input> Step1Async(Input input)
{
    await Task.Delay(100);
    return input;
}
